CREATE TABLE IF NOT EXISTS "consumers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Organisation or developer account name shown in the portal.
	"name" VARCHAR(200) NOT NULL,
	-- Identifier in the billing or CRM system. Null for self-serve signups that have never been invoiced.
	"external_reference" VARCHAR(64) UNIQUE,
	-- Where quota warnings and key expiry notices go. Getting this wrong is why keys expire in production unannounced.
	"contact_email" VARCHAR(320) NOT NULL,
	-- active | suspended | closed. Suspension must stop traffic without deleting keys, because a suspended account routinely comes back.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "consumers" IS 'The party that owns applications and is billed. Kept separate from applications because one customer legitimately runs several independent integrations with different keys and limits.';
COMMENT ON COLUMN "consumers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "consumers"."name" IS 'Organisation or developer account name shown in the portal.';
COMMENT ON COLUMN "consumers"."external_reference" IS 'Identifier in the billing or CRM system. Null for self-serve signups that have never been invoiced.';
COMMENT ON COLUMN "consumers"."contact_email" IS 'Where quota warnings and key expiry notices go. Getting this wrong is why keys expire in production unannounced.';
COMMENT ON COLUMN "consumers"."status" IS 'active | suspended | closed. Suspension must stop traffic without deleting keys, because a suspended account routinely comes back.';
COMMENT ON COLUMN "consumers"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "applications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account.
	"consumer_id" BIGINT NOT NULL,
	-- Application name, the unit developers recognise in dashboards.
	"name" VARCHAR(200) NOT NULL,
	-- sandbox | staging | production. Environment is on the application rather than the key so sandbox traffic never counts toward a paid quota.
	"environment" VARCHAR(16) NOT NULL DEFAULT 'production',
	-- What the integration does. Dull metadata that becomes valuable when deciding whether a key rotation will break something.
	"description" VARCHAR(500),
	-- Engineer responsible, which is not always the billing contact.
	"owner_email" VARCHAR(320),
	-- active | disabled. Disabling rejects every key under it in one write, which is the fastest lever during an incident.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "applications" IS 'One integration. It is the unit that rate limits, quotas, allowlists and usage are attributed to, because a key is a credential and credentials get rotated.';
COMMENT ON COLUMN "applications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "applications"."consumer_id" IS 'Owning account.';
COMMENT ON COLUMN "applications"."name" IS 'Application name, the unit developers recognise in dashboards.';
COMMENT ON COLUMN "applications"."environment" IS 'sandbox | staging | production. Environment is on the application rather than the key so sandbox traffic never counts toward a paid quota.';
COMMENT ON COLUMN "applications"."description" IS 'What the integration does. Dull metadata that becomes valuable when deciding whether a key rotation will break something.';
COMMENT ON COLUMN "applications"."owner_email" IS 'Engineer responsible, which is not always the billing contact.';
COMMENT ON COLUMN "applications"."status" IS 'active | disabled. Disabling rejects every key under it in one write, which is the fastest lever during an incident.';
COMMENT ON COLUMN "applications"."created_at" IS 'Creation time.';

CREATE INDEX "idx_applications_consumer_env"
ON "applications" ("consumer_id", "environment");

CREATE TABLE IF NOT EXISTS "api_keys" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application the key authenticates.
	"application_id" BIGINT NOT NULL,
	-- Short public portion shown in the UI and sent as the lookup key, e.g. ak_7f3d9b. It is what makes verifying a key one indexed read instead of hashing against every row.
	"key_prefix" VARCHAR(16) NOT NULL UNIQUE,
	-- Hash of the secret portion, never the secret. The gateway compares a hash on every request, so this is a fast keyed hash rather than a deliberately slow password hash.
	"key_hash" VARCHAR(255) NOT NULL,
	-- Scopes granted, as an array. A document because scopes are matched as a set on every request and nothing joins to an individual scope.
	"scopes" JSONB NOT NULL,
	-- active | rotating | revoked | expired. rotating means the old key still works during an overlap window, which is the only way a rotation happens without downtime.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Expiry instant. Null for a non-expiring key, which should be rare and visible.
	"expires_at" TIMESTAMPTZ,
	-- Last successful authentication. Written lazily — at most once a minute per key — because a write per request would make this the hottest row in the database.
	"last_used_at" TIMESTAMPTZ,
	-- When it was revoked. Kept rather than deleted so old request logs still resolve to a key.
	"revoked_at" TIMESTAMPTZ,
	-- Key this one supersedes, forming a rotation chain. Null for the first key of an application.
	"replaces_key_id" BIGINT,
	-- Issue time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "api_keys" IS 'A credential, stored as a prefix plus a hash so a database leak does not hand over working keys. Rotation is modelled as a chain of rows with an overlap window rather than as an update in place.';
COMMENT ON COLUMN "api_keys"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "api_keys"."application_id" IS 'Application the key authenticates.';
COMMENT ON COLUMN "api_keys"."key_prefix" IS 'Short public portion shown in the UI and sent as the lookup key, e.g. ak_7f3d9b. It is what makes verifying a key one indexed read instead of hashing against every row.';
COMMENT ON COLUMN "api_keys"."key_hash" IS 'Hash of the secret portion, never the secret. The gateway compares a hash on every request, so this is a fast keyed hash rather than a deliberately slow password hash.';
COMMENT ON COLUMN "api_keys"."scopes" IS 'Scopes granted, as an array. A document because scopes are matched as a set on every request and nothing joins to an individual scope.';
COMMENT ON COLUMN "api_keys"."status" IS 'active | rotating | revoked | expired. rotating means the old key still works during an overlap window, which is the only way a rotation happens without downtime.';
COMMENT ON COLUMN "api_keys"."expires_at" IS 'Expiry instant. Null for a non-expiring key, which should be rare and visible.';
COMMENT ON COLUMN "api_keys"."last_used_at" IS 'Last successful authentication. Written lazily — at most once a minute per key — because a write per request would make this the hottest row in the database.';
COMMENT ON COLUMN "api_keys"."revoked_at" IS 'When it was revoked. Kept rather than deleted so old request logs still resolve to a key.';
COMMENT ON COLUMN "api_keys"."replaces_key_id" IS 'Key this one supersedes, forming a rotation chain. Null for the first key of an application.';
COMMENT ON COLUMN "api_keys"."created_at" IS 'Issue time.';

CREATE INDEX "idx_keys_application_status"
ON "api_keys" ("application_id", "status");
CREATE INDEX "idx_keys_expiry"
ON "api_keys" ("expires_at");

CREATE TABLE IF NOT EXISTS "services" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable identifier used in config and in metric labels.
	"slug" VARCHAR(64) NOT NULL UNIQUE,
	-- Human name of the upstream service.
	"name" VARCHAR(160) NOT NULL,
	-- Base URL the gateway proxies to. One column rather than a host and port pair, because upstreams are increasingly named rather than addressed.
	"upstream_url" VARCHAR(400) NOT NULL,
	-- Upstream timeout. The gateway default exists so that one slow backend cannot exhaust the connection pool for everything else.
	"timeout_ms" INTEGER NOT NULL DEFAULT 30000,
	-- Automatic retries on connection failure. Defaults to zero because retrying a non-idempotent request is worse than failing it.
	"retry_count" SMALLINT NOT NULL DEFAULT 0,
	-- Path polled for readiness, used to take an upstream out of rotation before users find it.
	"health_path" VARCHAR(200),
	-- False takes every route on this service out of service at once.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "services" IS 'An upstream the gateway forwards to. Routes point at services rather than at URLs so that moving a backend is one row, not a search through route config.';
COMMENT ON COLUMN "services"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "services"."slug" IS 'Stable identifier used in config and in metric labels.';
COMMENT ON COLUMN "services"."name" IS 'Human name of the upstream service.';
COMMENT ON COLUMN "services"."upstream_url" IS 'Base URL the gateway proxies to. One column rather than a host and port pair, because upstreams are increasingly named rather than addressed.';
COMMENT ON COLUMN "services"."timeout_ms" IS 'Upstream timeout. The gateway default exists so that one slow backend cannot exhaust the connection pool for everything else.';
COMMENT ON COLUMN "services"."retry_count" IS 'Automatic retries on connection failure. Defaults to zero because retrying a non-idempotent request is worse than failing it.';
COMMENT ON COLUMN "services"."health_path" IS 'Path polled for readiness, used to take an upstream out of rotation before users find it.';
COMMENT ON COLUMN "services"."is_active" IS 'False takes every route on this service out of service at once.';

CREATE TABLE IF NOT EXISTS "routes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Upstream this route proxies to.
	"service_id" BIGINT NOT NULL,
	-- Match pattern, e.g. /v1/orders/:id. Stored as a pattern rather than a literal so usage aggregates group by endpoint instead of exploding per identifier.
	"path_pattern" VARCHAR(200) NOT NULL,
	-- GET | POST | PUT | PATCH | DELETE | ANY. Part of the route identity because a read and a write on the same path deserve different limits.
	"http_method" VARCHAR(10) NOT NULL DEFAULT 'GET',
	-- False for public endpoints such as health or a public catalogue. Public routes still need limits, which is why rate limiting is not coupled to authentication.
	"auth_required" BOOLEAN NOT NULL DEFAULT true,
	-- Scope a key must hold. Null when authentication alone is enough.
	"required_scope" VARCHAR(64),
	-- Policy overriding the plan default for this route. Null means the plan policy applies, and the override exists because one expensive search endpoint should not set the limit for everything.
	"rate_limit_policy_id" BIGINT,
	-- Whether the matched prefix is removed before forwarding, so upstreams need not know their public path.
	"strip_prefix" BOOLEAN NOT NULL DEFAULT false,
	-- Tie-break when two patterns match the same request. Explicit, because implicit longest-prefix rules are the source of the worst routing surprises.
	"priority" SMALLINT NOT NULL DEFAULT 0,
	-- False returns 404 without touching the upstream.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "routes" IS 'A published endpoint. Patterns, not literal paths, because every aggregate and every limit in the schema groups by route and an id in the path would shatter them.';
COMMENT ON COLUMN "routes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "routes"."service_id" IS 'Upstream this route proxies to.';
COMMENT ON COLUMN "routes"."path_pattern" IS 'Match pattern, e.g. /v1/orders/:id. Stored as a pattern rather than a literal so usage aggregates group by endpoint instead of exploding per identifier.';
COMMENT ON COLUMN "routes"."http_method" IS 'GET | POST | PUT | PATCH | DELETE | ANY. Part of the route identity because a read and a write on the same path deserve different limits.';
COMMENT ON COLUMN "routes"."auth_required" IS 'False for public endpoints such as health or a public catalogue. Public routes still need limits, which is why rate limiting is not coupled to authentication.';
COMMENT ON COLUMN "routes"."required_scope" IS 'Scope a key must hold. Null when authentication alone is enough.';
COMMENT ON COLUMN "routes"."rate_limit_policy_id" IS 'Policy overriding the plan default for this route. Null means the plan policy applies, and the override exists because one expensive search endpoint should not set the limit for everything.';
COMMENT ON COLUMN "routes"."strip_prefix" IS 'Whether the matched prefix is removed before forwarding, so upstreams need not know their public path.';
COMMENT ON COLUMN "routes"."priority" IS 'Tie-break when two patterns match the same request. Explicit, because implicit longest-prefix rules are the source of the worst routing surprises.';
COMMENT ON COLUMN "routes"."is_active" IS 'False returns 404 without touching the upstream.';

CREATE INDEX "idx_routes_service"
ON "routes" ("service_id");
CREATE UNIQUE INDEX "uq_routes_pattern_method"
ON "routes" ("path_pattern", "http_method");

CREATE TABLE IF NOT EXISTS "plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable code used in config and in checkout, e.g. free, growth, enterprise.
	"code" VARCHAR(32) NOT NULL UNIQUE,
	-- Display name on the pricing page.
	"name" VARCHAR(120) NOT NULL,
	-- Recurring price in minor currency units.
	"monthly_price_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of the money columns.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Requests included in a billing period before overage begins. Zero on a plan that is purely rate limited and never metered.
	"included_requests" BIGINT NOT NULL DEFAULT 0,
	-- Price per thousand requests beyond the included allowance. Per thousand, because per-request minor units round to zero and the rounding is where disputes start.
	"overage_price_per_thousand_minor" BIGINT NOT NULL DEFAULT 0,
	-- Default policy for every route under this plan, overridable per route.
	"rate_limit_policy_id" BIGINT,
	-- Cap on applications per consumer. Null means unlimited.
	"max_applications" SMALLINT,
	-- False for negotiated plans that must not appear on the pricing page but must still exist as rows.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plans" IS 'The commercial package. It names a rate limit policy and a quota, which keeps the technical limit and the billing allowance in one place instead of drifting apart.';
COMMENT ON COLUMN "plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plans"."code" IS 'Stable code used in config and in checkout, e.g. free, growth, enterprise.';
COMMENT ON COLUMN "plans"."name" IS 'Display name on the pricing page.';
COMMENT ON COLUMN "plans"."monthly_price_minor" IS 'Recurring price in minor currency units.';
COMMENT ON COLUMN "plans"."currency_code" IS 'ISO 4217 currency of the money columns.';
COMMENT ON COLUMN "plans"."included_requests" IS 'Requests included in a billing period before overage begins. Zero on a plan that is purely rate limited and never metered.';
COMMENT ON COLUMN "plans"."overage_price_per_thousand_minor" IS 'Price per thousand requests beyond the included allowance. Per thousand, because per-request minor units round to zero and the rounding is where disputes start.';
COMMENT ON COLUMN "plans"."rate_limit_policy_id" IS 'Default policy for every route under this plan, overridable per route.';
COMMENT ON COLUMN "plans"."max_applications" IS 'Cap on applications per consumer. Null means unlimited.';
COMMENT ON COLUMN "plans"."is_public" IS 'False for negotiated plans that must not appear on the pricing page but must still exist as rows.';

CREATE TABLE IF NOT EXISTS "rate_limit_policies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Policy name shown in the admin, e.g. 100 per second burst 200.
	"name" VARCHAR(120) NOT NULL,
	-- key | application | consumer | ip | route. The scope is the counter key: limiting per key and per application are different products and cannot share a counter.
	"scope" VARCHAR(16) NOT NULL DEFAULT 'application',
	-- fixed_window | sliding_window | token_bucket. Fixed windows allow double the limit across a boundary; token buckets absorb bursts. Storing the choice means it can be changed per plan without a deploy.
	"algorithm" VARCHAR(24) NOT NULL DEFAULT 'sliding_window',
	-- Length of the window the limit applies over. Sixty means per minute; one means per second.
	"window_seconds" INTEGER NOT NULL DEFAULT 60,
	-- Requests allowed within the window.
	"max_requests" INTEGER NOT NULL,
	-- Extra allowance for a token bucket, so a client that has been idle can spend its saved capacity. Null for window algorithms.
	"burst_size" INTEGER,
	-- reject | throttle | log_only. log_only is how a new limit is rolled out without breaking anyone, and it is the difference between a safe change and an outage.
	"on_exceed" VARCHAR(16) NOT NULL DEFAULT 'reject',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "rate_limit_policies" IS 'A reusable limit definition. Separating the policy from the plan and the route means the same limit can be applied in several places and changed once, and that a limit can be observed before it is enforced.';
COMMENT ON COLUMN "rate_limit_policies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "rate_limit_policies"."name" IS 'Policy name shown in the admin, e.g. 100 per second burst 200.';
COMMENT ON COLUMN "rate_limit_policies"."scope" IS 'key | application | consumer | ip | route. The scope is the counter key: limiting per key and per application are different products and cannot share a counter.';
COMMENT ON COLUMN "rate_limit_policies"."algorithm" IS 'fixed_window | sliding_window | token_bucket. Fixed windows allow double the limit across a boundary; token buckets absorb bursts. Storing the choice means it can be changed per plan without a deploy.';
COMMENT ON COLUMN "rate_limit_policies"."window_seconds" IS 'Length of the window the limit applies over. Sixty means per minute; one means per second.';
COMMENT ON COLUMN "rate_limit_policies"."max_requests" IS 'Requests allowed within the window.';
COMMENT ON COLUMN "rate_limit_policies"."burst_size" IS 'Extra allowance for a token bucket, so a client that has been idle can spend its saved capacity. Null for window algorithms.';
COMMENT ON COLUMN "rate_limit_policies"."on_exceed" IS 'reject | throttle | log_only. log_only is how a new limit is rolled out without breaking anyone, and it is the difference between a safe change and an outage.';

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account subscribed.
	"consumer_id" BIGINT NOT NULL,
	-- Plan subscribed to.
	"plan_id" BIGINT NOT NULL,
	-- trialing | active | past_due | cancelled. past_due is a distinct state because the usual policy is to keep serving traffic while chasing payment.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When this plan took effect.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it stops. Null while open ended. A plan change is a new row, not an edit, so a period is always billed on the plan in force during it.
	"ends_at" TIMESTAMPTZ,
	-- Negotiated allowance replacing the plan included amount. Null means take the plan value; enterprise deals are the reason this column exists.
	"quota_override_requests" BIGINT,
	-- Day of month the period rolls. Anchored per subscription so periods do not all close on the same night.
	"billing_day" SMALLINT NOT NULL DEFAULT 1,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'Which plan an account is on, over time. Modelled as intervals so an upgrade halfway through a month is expressible without rewriting the period that already ran.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."consumer_id" IS 'Account subscribed.';
COMMENT ON COLUMN "subscriptions"."plan_id" IS 'Plan subscribed to.';
COMMENT ON COLUMN "subscriptions"."status" IS 'trialing | active | past_due | cancelled. past_due is a distinct state because the usual policy is to keep serving traffic while chasing payment.';
COMMENT ON COLUMN "subscriptions"."started_at" IS 'When this plan took effect.';
COMMENT ON COLUMN "subscriptions"."ends_at" IS 'When it stops. Null while open ended. A plan change is a new row, not an edit, so a period is always billed on the plan in force during it.';
COMMENT ON COLUMN "subscriptions"."quota_override_requests" IS 'Negotiated allowance replacing the plan included amount. Null means take the plan value; enterprise deals are the reason this column exists.';
COMMENT ON COLUMN "subscriptions"."billing_day" IS 'Day of month the period rolls. Anchored per subscription so periods do not all close on the same night.';

CREATE INDEX "idx_subscriptions_consumer_status"
ON "subscriptions" ("consumer_id", "status");

CREATE TABLE IF NOT EXISTS "usage_counters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Key the traffic was attributed to.
	"api_key_id" BIGINT NOT NULL,
	-- Route counted, when the policy is per route. Null for an application-wide counter.
	"route_id" BIGINT,
	-- Start of the counting window, truncated to the window size. Truncation is what makes the upsert deterministic across gateway nodes.
	"window_start" TIMESTAMPTZ NOT NULL,
	-- Window length this row counts, so minute and day counters coexist in one table without ambiguity.
	"window_seconds" INTEGER NOT NULL,
	-- Requests in the window. Incremented by a flush job in batches, never once per request.
	"request_count" BIGINT NOT NULL DEFAULT 0,
	-- Requests refused by the limiter. The ratio against request_count is what tells you a limit is set too low before the support ticket does.
	"rejected_count" BIGINT NOT NULL DEFAULT 0,
	-- Last flush that touched this row. A window whose counter stopped advancing is how a dead gateway node is noticed.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "usage_counters" IS 'The durable half of rate limiting. Enforcement happens in memory at the edge — an atomic increment in Redis keyed by scope and truncated window — and every few seconds each node upserts its deltas here. The database holds the record of what was consumed; it is never in the path of a request.';
COMMENT ON COLUMN "usage_counters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "usage_counters"."api_key_id" IS 'Key the traffic was attributed to.';
COMMENT ON COLUMN "usage_counters"."route_id" IS 'Route counted, when the policy is per route. Null for an application-wide counter.';
COMMENT ON COLUMN "usage_counters"."window_start" IS 'Start of the counting window, truncated to the window size. Truncation is what makes the upsert deterministic across gateway nodes.';
COMMENT ON COLUMN "usage_counters"."window_seconds" IS 'Window length this row counts, so minute and day counters coexist in one table without ambiguity.';
COMMENT ON COLUMN "usage_counters"."request_count" IS 'Requests in the window. Incremented by a flush job in batches, never once per request.';
COMMENT ON COLUMN "usage_counters"."rejected_count" IS 'Requests refused by the limiter. The ratio against request_count is what tells you a limit is set too low before the support ticket does.';
COMMENT ON COLUMN "usage_counters"."updated_at" IS 'Last flush that touched this row. A window whose counter stopped advancing is how a dead gateway node is noticed.';

CREATE UNIQUE INDEX "uq_counters_key_route_window"
ON "usage_counters" ("api_key_id", "route_id", "window_start", "window_seconds");
CREATE INDEX "idx_counters_window_start"
ON "usage_counters" ("window_start");

CREATE TABLE IF NOT EXISTS "usage_aggregates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application the traffic belonged to. Aggregates key on the application, not the key, so a rotation does not split a customer usage chart in two.
	"application_id" BIGINT NOT NULL,
	-- Route aggregated. Null for an application total across all routes.
	"route_id" BIGINT,
	-- Start of the aggregation bucket.
	"period_start" TIMESTAMPTZ NOT NULL,
	-- hour | day | month. Coarser rows are built from finer ones and the finer ones are expired, which is what keeps a usage chart cheap after two years.
	"granularity" VARCHAR(8) NOT NULL DEFAULT 'hour',
	-- Total requests in the bucket.
	"request_count" BIGINT NOT NULL DEFAULT 0,
	-- Responses of 5xx. Separated from rejections because an upstream failure and a limit breach are different conversations.
	"error_count" BIGINT NOT NULL DEFAULT 0,
	-- Requests refused by rate limiting or quota.
	"rejected_count" BIGINT NOT NULL DEFAULT 0,
	-- Request bytes, which some plans price on.
	"bytes_in" BIGINT NOT NULL DEFAULT 0,
	-- Response bytes, usually the larger and more expensive direction.
	"bytes_out" BIGINT NOT NULL DEFAULT 0,
	-- Median latency in the bucket. Percentiles are stored rather than averages because an average hides exactly the tail anyone cares about.
	"latency_p50_ms" INTEGER,
	-- 95th percentile latency.
	"latency_p95_ms" INTEGER,
	-- 99th percentile latency.
	"latency_p99_ms" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "usage_aggregates" IS 'Pre-rolled metrics for dashboards and invoices. Built from the counters and the log stream rather than queried from raw requests, because a portal chart must not be allowed to scan a billion rows.';
COMMENT ON COLUMN "usage_aggregates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "usage_aggregates"."application_id" IS 'Application the traffic belonged to. Aggregates key on the application, not the key, so a rotation does not split a customer usage chart in two.';
COMMENT ON COLUMN "usage_aggregates"."route_id" IS 'Route aggregated. Null for an application total across all routes.';
COMMENT ON COLUMN "usage_aggregates"."period_start" IS 'Start of the aggregation bucket.';
COMMENT ON COLUMN "usage_aggregates"."granularity" IS 'hour | day | month. Coarser rows are built from finer ones and the finer ones are expired, which is what keeps a usage chart cheap after two years.';
COMMENT ON COLUMN "usage_aggregates"."request_count" IS 'Total requests in the bucket.';
COMMENT ON COLUMN "usage_aggregates"."error_count" IS 'Responses of 5xx. Separated from rejections because an upstream failure and a limit breach are different conversations.';
COMMENT ON COLUMN "usage_aggregates"."rejected_count" IS 'Requests refused by rate limiting or quota.';
COMMENT ON COLUMN "usage_aggregates"."bytes_in" IS 'Request bytes, which some plans price on.';
COMMENT ON COLUMN "usage_aggregates"."bytes_out" IS 'Response bytes, usually the larger and more expensive direction.';
COMMENT ON COLUMN "usage_aggregates"."latency_p50_ms" IS 'Median latency in the bucket. Percentiles are stored rather than averages because an average hides exactly the tail anyone cares about.';
COMMENT ON COLUMN "usage_aggregates"."latency_p95_ms" IS '95th percentile latency.';
COMMENT ON COLUMN "usage_aggregates"."latency_p99_ms" IS '99th percentile latency.';

CREATE UNIQUE INDEX "uq_aggregates_app_granularity_period"
ON "usage_aggregates" ("application_id", "granularity", "period_start");
CREATE INDEX "idx_aggregates_route_period"
ON "usage_aggregates" ("route_id", "period_start");

CREATE TABLE IF NOT EXISTS "request_logs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identifier echoed to the client in a response header. It is what a support ticket quotes, so it must be findable.
	"request_id" UUID NOT NULL,
	-- Distributed trace id, the join key to the tracing system where the upstream detail lives.
	"trace_id" VARCHAR(64),
	-- Key used. Null for an unauthenticated request or one rejected before the key was resolved.
	"api_key_id" BIGINT,
	-- Route matched. Null for a request that matched nothing, which is itself worth counting.
	"route_id" BIGINT,
	-- Request start instant. The partition key in any sane retention scheme.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- HTTP method.
	"method" VARCHAR(10) NOT NULL,
	-- Actual path requested, with identifiers, as opposed to the route pattern it matched.
	"path" VARCHAR(400) NOT NULL,
	-- Response status returned to the client, which is not always the upstream status — a 429 never reached an upstream at all.
	"status_code" SMALLINT NOT NULL,
	-- Total time to respond.
	"latency_ms" INTEGER,
	-- Time spent waiting on the upstream. The difference from latency_ms is the gateway own overhead, which is the number to watch during an incident.
	"upstream_latency_ms" INTEGER,
	-- Response size.
	"bytes_out" INTEGER,
	-- Source address, stored as inet so allowlist checks and subnet queries are index-supported rather than string matching.
	"client_ip" INET,
	-- Client user agent, the cheapest way to identify which SDK version is generating a pattern.
	"user_agent" VARCHAR(400),
	-- One in how many requests this row represents. Successes are sampled hard, errors are kept at one in one, and every count derived from this table must multiply by it or the numbers will be wrong in a way nobody notices.
	"sample_rate" SMALLINT NOT NULL DEFAULT 1,
	-- True for 5xx. Denormalised so the retention job can keep errors longer than successes without parsing status codes.
	"is_error" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "request_logs" IS 'Sampled request records for debugging, not for billing. Logging every request at gateway volume costs more than serving them, so successes are sampled and errors are not, and anything that must be exact reads the counters instead.';
COMMENT ON COLUMN "request_logs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "request_logs"."request_id" IS 'Identifier echoed to the client in a response header. It is what a support ticket quotes, so it must be findable.';
COMMENT ON COLUMN "request_logs"."trace_id" IS 'Distributed trace id, the join key to the tracing system where the upstream detail lives.';
COMMENT ON COLUMN "request_logs"."api_key_id" IS 'Key used. Null for an unauthenticated request or one rejected before the key was resolved.';
COMMENT ON COLUMN "request_logs"."route_id" IS 'Route matched. Null for a request that matched nothing, which is itself worth counting.';
COMMENT ON COLUMN "request_logs"."occurred_at" IS 'Request start instant. The partition key in any sane retention scheme.';
COMMENT ON COLUMN "request_logs"."method" IS 'HTTP method.';
COMMENT ON COLUMN "request_logs"."path" IS 'Actual path requested, with identifiers, as opposed to the route pattern it matched.';
COMMENT ON COLUMN "request_logs"."status_code" IS 'Response status returned to the client, which is not always the upstream status — a 429 never reached an upstream at all.';
COMMENT ON COLUMN "request_logs"."latency_ms" IS 'Total time to respond.';
COMMENT ON COLUMN "request_logs"."upstream_latency_ms" IS 'Time spent waiting on the upstream. The difference from latency_ms is the gateway own overhead, which is the number to watch during an incident.';
COMMENT ON COLUMN "request_logs"."bytes_out" IS 'Response size.';
COMMENT ON COLUMN "request_logs"."client_ip" IS 'Source address, stored as inet so allowlist checks and subnet queries are index-supported rather than string matching.';
COMMENT ON COLUMN "request_logs"."user_agent" IS 'Client user agent, the cheapest way to identify which SDK version is generating a pattern.';
COMMENT ON COLUMN "request_logs"."sample_rate" IS 'One in how many requests this row represents. Successes are sampled hard, errors are kept at one in one, and every count derived from this table must multiply by it or the numbers will be wrong in a way nobody notices.';
COMMENT ON COLUMN "request_logs"."is_error" IS 'True for 5xx. Denormalised so the retention job can keep errors longer than successes without parsing status codes.';

CREATE INDEX "idx_logs_time"
ON "request_logs" ("occurred_at");
CREATE INDEX "idx_logs_key_time"
ON "request_logs" ("api_key_id", "occurred_at");
CREATE INDEX "idx_logs_request_id"
ON "request_logs" ("request_id");

CREATE TABLE IF NOT EXISTS "ip_allowlist_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Application the restriction applies to.
	"application_id" BIGINT NOT NULL,
	-- Permitted network, stored as a cidr so containment is an indexed operator rather than string arithmetic. A single address is simply a /32.
	"cidr_block" CIDR NOT NULL,
	-- Why this range is trusted — an office, a NAT gateway, a partner. Six months later this is the only thing that makes the entry safe to remove.
	"description" VARCHAR(200),
	-- When it was added.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Automatic expiry. Null for permanent entries, but a temporary exception with no expiry is how allowlists rot into permitting everything.
	"expires_at" TIMESTAMPTZ,
	-- False disables the entry without losing the record of who trusted what.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ip_allowlist_entries" IS 'Network restrictions per application. An empty allowlist means unrestricted, which must be a deliberate, visible state rather than an accident of no rows existing.';
COMMENT ON COLUMN "ip_allowlist_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ip_allowlist_entries"."application_id" IS 'Application the restriction applies to.';
COMMENT ON COLUMN "ip_allowlist_entries"."cidr_block" IS 'Permitted network, stored as a cidr so containment is an indexed operator rather than string arithmetic. A single address is simply a /32.';
COMMENT ON COLUMN "ip_allowlist_entries"."description" IS 'Why this range is trusted — an office, a NAT gateway, a partner. Six months later this is the only thing that makes the entry safe to remove.';
COMMENT ON COLUMN "ip_allowlist_entries"."created_at" IS 'When it was added.';
COMMENT ON COLUMN "ip_allowlist_entries"."expires_at" IS 'Automatic expiry. Null for permanent entries, but a temporary exception with no expiry is how allowlists rot into permitting everything.';
COMMENT ON COLUMN "ip_allowlist_entries"."is_active" IS 'False disables the entry without losing the record of who trusted what.';

CREATE INDEX "idx_allowlist_app_active"
ON "ip_allowlist_entries" ("application_id", "is_active");

CREATE TABLE IF NOT EXISTS "billing_periods" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription being billed.
	"subscription_id" BIGINT NOT NULL,
	-- First day of the period, anchored to the subscription billing day.
	"period_start" DATE NOT NULL,
	-- Last day of the period.
	"period_end" DATE NOT NULL,
	-- Allowance for this period, copied from the plan or the negotiated override at period open. Snapshotted, so a plan price change cannot retroactively alter a closed period.
	"included_requests" BIGINT NOT NULL DEFAULT 0,
	-- Requests consumed, summed from the counters at close. Counters rather than logs, because logs are sampled and an invoice may not be.
	"actual_requests" BIGINT NOT NULL DEFAULT 0,
	-- Requests beyond the allowance. Stored rather than derived so a goodwill adjustment is possible without rewriting usage.
	"overage_requests" BIGINT NOT NULL DEFAULT 0,
	-- Charge for the overage in minor units, computed at the rate in force during the period.
	"overage_amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of overage_amount_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- open | closed | invoiced | disputed. A closed period is immutable; a dispute is resolved with a credit, not an edit.
	"status" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- When the period was finalised, after the last counter flush has certainly landed.
	"closed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "billing_periods" IS 'The metered bill for one period. Allowance and price are snapshotted at open and the totals are frozen at close, because the one thing a usage-based bill must be is reproducible months later.';
COMMENT ON COLUMN "billing_periods"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "billing_periods"."subscription_id" IS 'Subscription being billed.';
COMMENT ON COLUMN "billing_periods"."period_start" IS 'First day of the period, anchored to the subscription billing day.';
COMMENT ON COLUMN "billing_periods"."period_end" IS 'Last day of the period.';
COMMENT ON COLUMN "billing_periods"."included_requests" IS 'Allowance for this period, copied from the plan or the negotiated override at period open. Snapshotted, so a plan price change cannot retroactively alter a closed period.';
COMMENT ON COLUMN "billing_periods"."actual_requests" IS 'Requests consumed, summed from the counters at close. Counters rather than logs, because logs are sampled and an invoice may not be.';
COMMENT ON COLUMN "billing_periods"."overage_requests" IS 'Requests beyond the allowance. Stored rather than derived so a goodwill adjustment is possible without rewriting usage.';
COMMENT ON COLUMN "billing_periods"."overage_amount_minor" IS 'Charge for the overage in minor units, computed at the rate in force during the period.';
COMMENT ON COLUMN "billing_periods"."currency_code" IS 'ISO 4217 currency of overage_amount_minor.';
COMMENT ON COLUMN "billing_periods"."status" IS 'open | closed | invoiced | disputed. A closed period is immutable; a dispute is resolved with a credit, not an edit.';
COMMENT ON COLUMN "billing_periods"."closed_at" IS 'When the period was finalised, after the last counter flush has certainly landed.';

CREATE UNIQUE INDEX "uq_periods_subscription_start"
ON "billing_periods" ("subscription_id", "period_start");
CREATE INDEX "idx_periods_status"
ON "billing_periods" ("status");

